local function newStartupTrace()
    local started=os.clock()
    local file="JcHub_SAE_Startup_"..os.time().."_"..math.floor(started*1000)..".log"
    local append=appendfile
    local output=warn or print
    return function(stage,detail)
        local text=tostring(detail or ""):gsub("[\r\n]"," "):sub(1,1400)
        text=text:gsub("https?://[%w%.%-]*discord[%w%.%-]*/api/webhooks/[^%s]+","[WEBHOOK REDACTED]")
        local line=string.format("[JcHub SAE STARTUP v1.0.4] +%.3fs %s%s",os.clock()-started,stage,text~="" and " | "..text or "")
        pcall(output,line)
        if type(append)=="function" then pcall(append,file,line.."\n") end
    end
end

